#!/usr/bin/env node
/**
 * Bundle the Talk realizer and the language packs into TikoKit, for iOS.
 *
 * The realizer is one implementation in TypeScript, shared by the worker and the web
 * app. Porting it to Swift would make a second implementation of 54 languages of
 * grammar to keep in step with the first — which is the mistake this repo already
 * avoids for app configs, colours and locales by generating both platforms from one
 * source. So iOS runs the same code, in JavaScriptCore, from a bundle generated here.
 *
 * Writes into `packages/tikokit-ios/Sources/TikoKit/Resources/`:
 *
 * - `talk-realizer.js` — the realizer as one file, exposing `tikoRealize(json)`
 * - `talk-packs/<locale>-v1.json` — every language pack, so the board works offline
 *
 * The Swift side is `TikoSentence.swift`; it evaluates the bundle once and calls in
 * with JSON. Nothing is downloaded, and nothing is evaluated that did not ship in the
 * app — which is what Apple's rules require and what a child on a train needs.
 *
 * Usage:
 *   node tools/generate-talk-realizer-bundle.mjs
 *   node tools/generate-talk-realizer-bundle.mjs --check
 */
import { build } from 'esbuild'
import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, rmSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const RESOURCES = join(ROOT, 'packages/tikokit-ios/Sources/TikoKit/Resources')
const PACKS_SOURCE = join(ROOT, 'packages/talk-packs/data')
const PACKS_TARGET = join(RESOURCES, 'talk-packs')
const CHECK = process.argv.includes('--check')

/**
 * The entry point handed to JavaScriptCore. JSC and Swift talk most simply in
 * strings, so the whole call is one JSON object in and one out — and the notes come
 * back with it, because a caller that wants to know why a sentence looks like that
 * should be able to ask.
 */
const ENTRY = `
import { realize, lexicons, languages, supportedLanguages } from './packages/talk-realizer/src/index'

/**
 * @param {string} payload JSON: { words, locale, negated?, tense?, speakerGender?, custom? }
 * @returns {string} JSON: { text, strip, notes, inserted }
 */
globalThis.tikoRealize = function tikoRealize(payload) {
  try {
    const input = JSON.parse(payload)
    const code = String(input.locale || 'en').split('-')[0].toLowerCase()
    const lexicon = Object.assign({}, lexicons[code] || {})
    // A word the child added is a name, and a name takes no article.
    for (const id of input.custom || []) {
      const word = (input.words || []).find((candidate) => candidate.id === id)
      if (word && word.pos === 'noun') lexicon[id] = { pos: 'noun', proper: true }
    }
    const result = realize(input.words || [], {
      locale: code,
      lexicon,
      negated: input.negated,
      tense: input.tense,
      speakerGender: input.speakerGender,
    })
    return JSON.stringify({
      text: result.text,
      // The strip a child is still building: the same grammar without the
      // terminator, in every script the realizer writes.
      strip: result.text.replace(/[.\\u3002\\uFF01\\uFF1F?!\\u0964\\u0965\\u0589]+$/, ''),
      notes: result.notes,
      inserted: result.inserted,
    })
  } catch (error) {
    return JSON.stringify({ error: String(error && error.message ? error.message : error) })
  }
}

/** Which languages have grammar, for a Swift caller that wants to ask. */
globalThis.tikoRealizerLanguages = function tikoRealizerLanguages() {
  return JSON.stringify(supportedLanguages.filter((code) => languages[code]))
}
`

async function bundle() {
  const result = await build({
    stdin: {
      contents: ENTRY,
      resolveDir: ROOT,
      sourcefile: 'tiko-realizer-entry.js',
      loader: 'js',
    },
    bundle: true,
    format: 'iife',
    platform: 'neutral',
    target: ['es2020'],
    // JavaScriptCore has no console by default and the realizer does not use one,
    // but a stray reference would be fatal, so it is stubbed rather than assumed.
    banner: { js: 'var console = console || { log: function () {}, warn: function () {}, error: function () {} };' },
    minify: true,
    write: false,
    legalComments: 'none',
  })
  return result.outputFiles[0].text
}

const header = [
  '// Generated by tools/generate-talk-realizer-bundle.mjs — do not edit.',
  '// The Talk realizer, bundled for JavaScriptCore. Source: packages/talk-realizer.',
  '',
].join('\n')

const js = header + await bundle()
const jsTarget = join(RESOURCES, 'talk-realizer.js')

const packFiles = readdirSync(PACKS_SOURCE).filter((name) => name.endsWith('.json')).sort()

let stale = false

function writeIfChanged(target, contents, label) {
  const previous = existsSync(target) ? readFileSync(target, 'utf8') : null
  if (previous === contents) return false
  if (CHECK) {
    console.error(`STALE ${label}`)
    stale = true
    return false
  }
  writeFileSync(target, contents)
  return true
}

mkdirSync(RESOURCES, { recursive: true })
if (writeIfChanged(jsTarget, js, 'talk-realizer.js')) {
  console.log(`Wrote talk-realizer.js — ${(js.length / 1024).toFixed(0)} KiB`)
} else if (!stale) {
  console.log('OK   talk-realizer.js is up to date')
}

// The packs: copied rather than referenced, because an iOS resource bundle cannot
// reach outside the target's own directory.
if (!CHECK) mkdirSync(PACKS_TARGET, { recursive: true })
let copied = 0
let bytes = 0
for (const file of packFiles) {
  const contents = readFileSync(join(PACKS_SOURCE, file), 'utf8')
  bytes += contents.length
  if (writeIfChanged(join(PACKS_TARGET, file), contents, `talk-packs/${file}`)) copied += 1
}
// A pack that was deleted upstream should not linger in the app.
if (!CHECK && existsSync(PACKS_TARGET)) {
  for (const existing of readdirSync(PACKS_TARGET)) {
    if (!packFiles.includes(existing)) {
      rmSync(join(PACKS_TARGET, existing))
      console.log(`Removed talk-packs/${existing}`)
    }
  }
}

console.log(
  `${packFiles.length} packs (${(bytes / 1024 / 1024).toFixed(1)} MiB)`
  + `${copied ? `, ${copied} written` : ', all up to date'}`,
)
if (stale) process.exit(1)
